#include <vector>
#include <queue>

using namespace std;

struct Node {
    long long val;
    int idx;
    int prev;
    int next;
};

class Solution {
public:
    int minimumPairRemoval(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return 0;

        vector<Node> nodes(n);
        for (int i = 0; i < n; ++i) {
            nodes[i] = {(long long)nums[i], i, i - 1, i + 1 < n ? i + 1 : -1};
        }

        int inversions = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (nodes[i].val > nodes[i + 1].val) inversions++;
        }

        using P = pair<long long, int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        vector<bool> active(n, true);
        for (int i = 0; i < n - 1; ++i) {
            pq.push({nodes[i].val + nodes[i + 1].val, i});
        }

        int ops = 0;
        while (inversions > 0) {
            int leftIdx = -1, rightIdx = -1;
            while (!pq.empty()) {
                auto [s, i] = pq.top(); pq.pop();
                if (!active[i]) continue;
                int nxt = nodes[i].next;
                if (nxt == -1 || !active[nxt]) continue;
                if (nodes[i].val + nodes[nxt].val == s) {
                    leftIdx = i;
                    rightIdx = nxt;
                    break;
                }
            }
            if (leftIdx == -1) break;

            ops++;
            int p = nodes[leftIdx].prev;
            int nxt = nodes[rightIdx].next;
            if (p != -1 && nodes[p].val > nodes[leftIdx].val) inversions--;
            if (nodes[leftIdx].val > nodes[rightIdx].val) inversions--;
            if (nxt != -1 && nodes[rightIdx].val > nodes[nxt].val) inversions--;

            nodes[leftIdx].val += nodes[rightIdx].val;
            active[rightIdx] = false;
            nodes[leftIdx].next = nxt;
            if (nxt != -1) nodes[nxt].prev = leftIdx;

            if (p != -1 && nodes[p].val > nodes[leftIdx].val) inversions++;
            if (nxt != -1 && nodes[leftIdx].val > nodes[nxt].val) inversions++;

            if (p != -1) pq.push({nodes[p].val + nodes[leftIdx].val, p});
            if (nxt != -1) pq.push({nodes[leftIdx].val + nodes[nxt].val, leftIdx});
        }
        return ops;
    }
};

import java.util.*;

class Solution {
    static class Node {
        long val;
        int idx, prev, next;
        Node(long val, int idx, int prev, int next) {
            this.val = val; this.idx = idx; this.prev = prev; this.next = next;
        }
    }

    public int minimumPairRemoval(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;

        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(nums[i], i, i - 1, i + 1 < n ? i + 1 : -1);
        }

        int inversions = 0;
        for (int i = 0; i < n - 1; i++) {
            if (nodes[i].val > nodes[i + 1].val) inversions++;
        }

        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        boolean[] active = new boolean[n];
        Arrays.fill(active, true);
        for (int i = 0; i < n - 1; i++) {
            pq.offer(new long[]{nodes[i].val + nodes[i + 1].val, i});
        }

        int ops = 0;
        while (inversions > 0) {
            int leftIdx = -1, rightIdx = -1;
            while (!pq.isEmpty()) {
                long[] top = pq.poll();
                int i = (int) top[1];
                if (!active[i]) continue;
                int nxt = nodes[i].next;
                if (nxt == -1 || !active[nxt]) continue;
                if (nodes[i].val + nodes[nxt].val == top[0]) {
                    leftIdx = i; rightIdx = nxt; break;
                }
            }
            if (leftIdx == -1) break;

            ops++;
            int p = nodes[leftIdx].prev;
            int nxt = nodes[rightIdx].next;
            if (p != -1 && nodes[p].val > nodes[leftIdx].val) inversions--;
            if (nodes[leftIdx].val > nodes[rightIdx].val) inversions--;
            if (nxt != -1 && nodes[rightIdx].val > nodes[nxt].val) inversions--;

            nodes[leftIdx].val += nodes[rightIdx].val;
            active[rightIdx] = false;
            nodes[leftIdx].next = nxt;
            if (nxt != -1) nodes[nxt].prev = leftIdx;

            if (p != -1 && nodes[p].val > nodes[leftIdx].val) inversions++;
            if (nxt != -1 && nodes[leftIdx].val > nodes[nxt].val) inversions++;

            if (p != -1) pq.offer(new long[]{nodes[p].val + nodes[leftIdx].val, p});
            if (nxt != -1) pq.offer(new long[]{nodes[leftIdx].val + nodes[nxt].val, leftIdx});
        }
        return ops;
    }
}

var minimumPairRemoval = function(nums) {
    const n = nums.length;
    if (n < 2) return 0;

    const nodes = [];
    for (let i = 0; i < n; i++) {
        nodes.push({ val: nums[i], idx: i, prev: i - 1, next: i + 1 < n ? i + 1 : -1 });
    }

    let inversions = 0;
    for (let i = 0; i < n - 1; i++) {
        if (nodes[i].val > nodes[i + 1].val) inversions++;
    }

    const active = new Array(n).fill(true);
    let ops = 0;

    while (inversions > 0) {
        let minSum = Infinity;
        let leftIdx = -1;
        for (let i = 0; i < n; i++) {
            if (!active[i] || nodes[i].next === -1) continue;
            const s = nodes[i].val + nodes[nodes[i].next].val;
            if (s < minSum) {
                minSum = s;
                leftIdx = i;
            }
        }
        if (leftIdx === -1) break;

        const rightIdx = nodes[leftIdx].next;
        ops++;
        const p = nodes[leftIdx].prev;
        const nxt = nodes[rightIdx].next;
        if (p !== -1 && nodes[p].val > nodes[leftIdx].val) inversions--;
        if (nodes[leftIdx].val > nodes[rightIdx].val) inversions--;
        if (nxt !== -1 && nodes[rightIdx].val > nodes[nxt].val) inversions--;

        nodes[leftIdx].val += nodes[rightIdx].val;
        active[rightIdx] = false;
        nodes[leftIdx].next = nxt;
        if (nxt !== -1) nodes[nxt].prev = leftIdx;

        if (p !== -1 && nodes[p].val > nodes[leftIdx].val) inversions++;
        if (nxt !== -1 && nodes[leftIdx].val > nodes[nxt].val) inversions++;
    }
    return ops;
};
